import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week4/generated/day3-script-level.spec.ts", `// Week 4, Day 3 — changing settings for YOUR test, not for the whole team.
//
// Everything here overrides a config value from inside the spec. The root
// playwright.config.ts is never touched, so nobody else's run changes.
//
// Written by a cell in week4/day3_2.ipynb. Run it yourself:
//   npx playwright test week4/generated/day3-script-level.spec.ts
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Script-level overrides", () => {
  // Applies to this group only. The config's fullyParallel setting is untouched.
  test.describe.configure({ mode: "parallel" });

  test("A — runs in parallel with its siblings", async ({ page }) => {
    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("B — independent, so parallel is safe", async ({ page }) => {
    await loginAs(page);
    await expect(page.getByText("Account Balance", { exact: true })).toBeVisible();
  });

  test("C — three fresh contexts, no shared state", async ({ page }) => {
    await loginAs(page);
    await expect(page.getByRole("button", { name: "LogOut" })).toBeVisible();
  });
});

test.describe("Test-level timeout", () => {
  test("this one test gets a longer budget", async ({ page }) => {
    // Raises the deadline for THIS test only. The config default still applies
    // to every other test in the suite.
    test.setTimeout(60_000);

    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("and this one keeps the default", async ({ page }) => {
    await loginAs(page);
    // Proof the override above did not leak: this test's budget is whatever the
    // config says, not 60s.
    expect(test.info().timeout).toBeLessThan(60_000);
  });

  test("test.slow() triples the budget instead of naming a number", async ({ page }) => {
    const before = test.info().timeout;
    test.slow();
    expect(test.info().timeout).toBe(before * 3);

    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();
  });
});

test.describe("What cannot be overridden per test", () => {
  test("the expect() deadline is per-assertion, not per-test", async ({ page }) => {
    await loginAs(page);

    // There is no test.setExpectTimeout(). The assertion budget is either a
    // config value (expect.timeout) or an option on the individual assertion.
    await expect(page.getByText("Leela")).toBeVisible({ timeout: 9_000 });

    // test.setTimeout changes the TEST budget; it does nothing to expect().
    test.setTimeout(45_000);
    await expect(page.getByRole("button", { name: "LogOut" })).toBeVisible({ timeout: 3_000 });
  });
});
`);

await runSpec("week4/generated/day3-script-level.spec.ts");

// The three forms, as plain data — this is what you would write.
const forms = {
  oneAssertion: 'await expect(locator).toBeVisible({ timeout: 9_000 });',
  oneTest:      'test.setTimeout(60_000);   // first line inside the test',
  tripleIt:     'test.slow();               // 3x whatever the config says',
  wholeSuite:   '{ timeout: 60_000 }        // in playwright.config.ts',
};

for (const [name, code] of Object.entries(forms)) {
  console.log(`${name.padEnd(13)} ${code}`);
}

// Sort a handful of real decisions into the right home.
const decisions = [
  { want: "watch a test in a browser",            home: "CLI    --headed" },
  { want: "this group can run in parallel",        home: "spec   describe.configure" },
  { want: "this one journey is genuinely slow",    home: "spec   test.slow()" },
  { want: "traces kept on failure",                home: "config trace: retain-on-failure" },
  { want: "run only one test while debugging",     home: "CLI    -g \"name\"" },
  { want: "the app under test lives here",         home: "config baseURL" },
  { want: "CI is slower than my laptop",           home: "config process.env.CI ? ... : ..." },
  { want: "try three workers, once",               home: "CLI    --workers=3" },
];

for (const d of decisions) console.log(`${d.want.padEnd(36)} -> ${d.home}`);
